/* v11 Skyshader: Codex-painted sky ingredients as data URIs, so WebGL may sample them over file:// (a file:// image would taint the canvas).
   Sources (see PROMPTS.md): cloud <- cloud-a.png, cirrus <- cirrus-a.png, milky <- milky-a.png, town <- town-a.png. Copies as webp in assets/sky/. */
window.SKY_TEX = {
  cloud: "data:image/webp;base64,",
  cirrus: "data:image/webp;base64,",
  milky: "data:image/webp;base64,",
  town: "data:image/webp;base64,"
};
